From 9a630bdc9f9f6e5ecd9776e9ef42184dbcf0f786 Mon Sep 17 00:00:00 2001
From: Cristy <urban-warrior@imagemagick.org>
Date: Sun, 18 Sep 2022 08:03:51 -0400
Subject: [PATCH] earlier check for maximum channels

---
 coders/tiff.c | 5 +++--
 1 file changed, 3 insertions(+), 2 deletions(-)

diff --git a/coders/tiff.c b/coders/tiff.c
index b69e0c6..0328114 100644
--- a/coders/tiff.c
+++ b/coders/tiff.c
@@ -1348,7 +1348,9 @@ static Image *ReadTIFFImage(const ImageInfo *image_info,
         TIFFClose(tiff);
         ThrowReaderException(CorruptImageError,"UnsupportedBitsPerPixel");
       }
-    if (samples_per_pixel > MaxPixelChannels)
+    tiff_status=TIFFGetFieldDefaulted(tiff,TIFFTAG_EXTRASAMPLES,&extra_samples,
+      &sample_info,sans);
+    if ((samples_per_pixel+extra_samples) > MaxPixelChannels)
       {
         TIFFClose(tiff);
         ThrowReaderException(CorruptImageError,"MaximumChannelsExceeded");
@@ -1683,7 +1685,6 @@ static Image *ReadTIFFImage(const ImageInfo *image_info,
       default:
         break;
     }
-    extra_samples=0;
     tiff_status=TIFFGetFieldDefaulted(tiff,TIFFTAG_EXTRASAMPLES,&extra_samples,
       &sample_info,sans);
     if (tiff_status == 1)
